parameters.jsCode:
const items = $input.all();

for (const item of items) {
  item.json.Session_ID = item.json.sessionId || 'session_sin_id';
  item.json.mensajeActual = item.json.chatInput || '';
  item.json.Cantidad_mensajes = Number(item.json.Cantidad_mensajes || 0) + 1;
}

return items;
